"""Get the root name of a Python simulation.

    Extracts both the file path and the root name of the simulation.

    Parameters
    ----------
    fp: str
        The directory path to a Python .pf file

    Returns
    -------
    root: str
        The root name of the Python simulation
    where: str
        The directory path containing the provided Python .pf file
    """
def get_root_name(fp: Any) -> object {
    if (`type(fp) is not str) {
        raise TypeError(
            "expected a string as input for the file path, not whatever you put"
        );
    }
    dot = fp.rfind(".");
    slash = fp.rfind("/");
    `root = fp[(slash + 1):dot];
    fp = fp[:(slash + 1)];
    if (fp == "") {
        fp = "./";
    }
    return (`root, fp);
}

