"""
    Return the smallest multiple of 4KiB not less than the total of the loadable
    segments.  (In other words, the size will be returned as-is if it is an
    exact multiple of 4KiB, otherwise it is rounded up to the next higher
    multiple of 4KiB.)
    """
def get_aligned_size(n: int) -> int {
    return n if ((n % 4096) == 0) else (((n // 4096) + 1) * 4096);
}

"""Convenience function used to make sure that a sequence is always
    represented by a list of symbols. Sometimes a single-symbol
    sequence is passed in the form of a string representing the
    symbol. This has to be converted to a one-item list for
    consistency, as a list of symbols is what many of the following
    functions expect.

    """
def as_list(arg: Any) -> object {
    if isinstance(arg, str) {
        listed_arg = [arg];
    } else {
        listed_arg = arg[:];
    }
    return listed_arg;
}
